-- Generated by drizzle-kit, then hand-guarded. IDEMPOTENT: runs on every container start.
-- Pilot societies (societies.tier / verified_at) and co-admin nominations
-- (admin_requests: nominate_admin kind, nominated/declined/cancelled statuses,
-- residence proof, nominator, 48 h auto-approve). Additive: no data is removed.
--
-- admin_requests.kind / status move from pg enums to text + CHECK. drizzle runs
-- every pending migration in ONE transaction, and a value added with
-- ALTER TYPE ... ADD VALUE can't be used in the transaction that added it, so
-- the partial indexes below couldn't mention 'nominate_admin' otherwise.
-- The two partial indexes that compare against enum literals are dropped first
-- (their predicates wouldn't type-check against a text column) and recreated.
DROP INDEX IF EXISTS "admin_requests_one_pending_join";--> statement-breakpoint
DROP INDEX IF EXISTS "admin_requests_one_pending_new";--> statement-breakpoint
ALTER TABLE "admin_requests" DROP CONSTRAINT IF EXISTS "admin_requests_shape";--> statement-breakpoint
ALTER TABLE "admin_requests" ALTER COLUMN "status" DROP DEFAULT;--> statement-breakpoint
ALTER TABLE "admin_requests" ALTER COLUMN "kind" SET DATA TYPE text USING "kind"::text;--> statement-breakpoint
ALTER TABLE "admin_requests" ALTER COLUMN "status" SET DATA TYPE text USING "status"::text;--> statement-breakpoint
ALTER TABLE "admin_requests" ALTER COLUMN "status" SET DEFAULT 'pending';--> statement-breakpoint
DROP TYPE IF EXISTS "public"."admin_request_kind";--> statement-breakpoint
DROP TYPE IF EXISTS "public"."admin_request_status";--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "admin_requests_one_pending_join" ON "admin_requests" USING btree ("requester_id","society_id") WHERE status = 'pending' and kind = 'join_admin';--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "admin_requests_one_pending_new" ON "admin_requests" USING btree ("requester_id") WHERE status = 'pending' and kind = 'new_society';--> statement-breakpoint
-- RWA certificate / authorisation letter are no longer asked for; the columns
-- stay for older rows. ID proof is null only on an unaccepted nomination
-- (admin_requests_id_proof below).
ALTER TABLE "admin_requests" ALTER COLUMN "authorization_key" DROP NOT NULL;--> statement-breakpoint
ALTER TABLE "admin_requests" ALTER COLUMN "id_proof_key" DROP NOT NULL;--> statement-breakpoint
ALTER TABLE "admin_requests" ADD COLUMN IF NOT EXISTS "residence_proof_key" text;--> statement-breakpoint
ALTER TABLE "admin_requests" ADD COLUMN IF NOT EXISTS "nominated_by" uuid;--> statement-breakpoint
ALTER TABLE "admin_requests" ADD COLUMN IF NOT EXISTS "nominee_accepted_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "admin_requests" ADD COLUMN IF NOT EXISTS "auto_approve_at" timestamp with time zone;--> statement-breakpoint
-- Existing societies were vetted under the old document rules: verified.
ALTER TABLE "societies" ADD COLUMN IF NOT EXISTS "tier" text DEFAULT 'verified' NOT NULL;--> statement-breakpoint
ALTER TABLE "societies" ADD COLUMN IF NOT EXISTS "verified_at" timestamp with time zone;--> statement-breakpoint
DO $$ BEGIN
 ALTER TABLE "admin_requests" ADD CONSTRAINT "admin_requests_nominated_by_users_id_fk" FOREIGN KEY ("nominated_by") REFERENCES "public"."users"("id") ON DELETE no action ON UPDATE no action;
EXCEPTION
 WHEN duplicate_object THEN null;
END $$;
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "admin_requests_society" ON "admin_requests" USING btree ("society_id","created_at");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "admin_requests_auto_approve" ON "admin_requests" USING btree ("auto_approve_at") WHERE status = 'pending' and auto_approve_at is not null;--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "admin_requests_one_open_nomination" ON "admin_requests" USING btree ("requester_id","society_id") WHERE status in ('nominated', 'pending') and kind = 'nominate_admin';--> statement-breakpoint
DO $$ BEGIN
 ALTER TABLE "admin_requests" ADD CONSTRAINT "admin_requests_kind" CHECK ("admin_requests"."kind" in ('new_society', 'join_admin', 'nominate_admin'));
EXCEPTION
 WHEN duplicate_object THEN null;
END $$;
--> statement-breakpoint
DO $$ BEGIN
 ALTER TABLE "admin_requests" ADD CONSTRAINT "admin_requests_status" CHECK ("admin_requests"."status" in ('nominated', 'pending', 'approved', 'rejected', 'withdrawn', 'declined', 'cancelled'));
EXCEPTION
 WHEN duplicate_object THEN null;
END $$;
--> statement-breakpoint
DO $$ BEGIN
 ALTER TABLE "admin_requests" ADD CONSTRAINT "admin_requests_shape_v2" CHECK (("admin_requests"."kind" in ('join_admin', 'nominate_admin') and "admin_requests"."society_id" is not null) or ("admin_requests"."kind" = 'new_society' and "admin_requests"."society_name" is not null and "admin_requests"."city" is not null and "admin_requests"."address" is not null and "admin_requests"."center_lat" is not null and "admin_requests"."center_lng" is not null and "admin_requests"."radius_m" is not null and "admin_requests"."tower_name" is not null and "admin_requests"."flat_no" is not null and "admin_requests"."occupancy" in ('owner', 'tenant', 'family')));
EXCEPTION
 WHEN duplicate_object THEN null;
END $$;
--> statement-breakpoint
DO $$ BEGIN
 ALTER TABLE "admin_requests" ADD CONSTRAINT "admin_requests_nominator" CHECK (("admin_requests"."kind" = 'nominate_admin') = ("admin_requests"."nominated_by" is not null));
EXCEPTION
 WHEN duplicate_object THEN null;
END $$;
--> statement-breakpoint
DO $$ BEGIN
 ALTER TABLE "admin_requests" ADD CONSTRAINT "admin_requests_id_proof" CHECK ("admin_requests"."id_proof_key" is not null or ("admin_requests"."kind" = 'nominate_admin' and "admin_requests"."status" in ('nominated', 'declined', 'cancelled')));
EXCEPTION
 WHEN duplicate_object THEN null;
END $$;
--> statement-breakpoint
DO $$ BEGIN
 ALTER TABLE "societies" ADD CONSTRAINT "societies_tier" CHECK ("societies"."tier" in ('pilot', 'verified'));
EXCEPTION
 WHEN duplicate_object THEN null;
END $$;
